import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';
import CustomerSearch from '../../components/CustomerSearch';

export default function AdminCheckout() {
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [fiatAmount, setFiatAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [sessionActive, setSessionActive] = useState(false);
  const [sessionDetails, setSessionDetails] = useState(null);

  // In production, this comes from the logged-in admin's context/localStorage
  const adminInfo = JSON.parse(localStorage.getItem('adminInfo'));
  const companyId = adminInfo?._id || process.env.REACT_APP_COMPANY_ID; 

  useEffect(() => {
    if (companyId) {
      API.get(`/users/company/${companyId}`)
        .then(res => setUsers(res.data))
        .catch(() => toast.error('Failed to load customer database'));
    }
  }, [companyId]);

  const handleStartCheckout = async (e) => {
    e.preventDefault();
    if (!selectedUserId) return toast.error("Please select a valid customer");
    
    setLoading(true);
    setSessionDetails(null);

    try {
      const { data } = await API.post('/transactions/initiate', {
        companyId,
        userId: selectedUserId,
        fiatAmount: Number(fiatAmount)
      });
      toast.success(data.message);
      setSessionActive(true);
      setSessionDetails(data);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Checkout initiation failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-lg p-8 bg-white rounded-2xl shadow-lg border border-gray-100 space-y-6 mx-auto mt-10">
      <div>
        <h2 className="text-2xl font-bold text-gray-900">POS Checkout Terminal</h2>
        <p className="text-sm text-gray-500">Search customer, input bill, and lock terminal.</p>
      </div>

      <form onSubmit={handleStartCheckout} className="space-y-4">
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Customer Search</label>
          {/* Replaced <select> with our scalable component */}
          <CustomerSearch 
            users={users} 
            selectedUserId={selectedUserId} 
            onSelect={setSelectedUserId} 
          />
        </div>

        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Bill Amount (₦)</label>
          <input
            type="number"
            value={fiatAmount}
            onChange={(e) => setFiatAmount(e.target.value)}
            required
            disabled={sessionActive}
            placeholder="e.g. 2500"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
          />
        </div>

        <button
          type="submit"
          disabled={loading || sessionActive}
          className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition duration-200 disabled:opacity-50 shadow-sm"
        >
          {sessionActive ? 'Terminal Locked — Waiting for Tap' : 'Push to Terminal'}
        </button>
      </form>

      {sessionActive && (
        <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl space-y-2 animate-pulse">
          <p className="text-xs font-bold text-amber-800 uppercase tracking-wide">Active Session Locked</p>
          <p className="text-sm text-amber-700">Required Points: <span className="font-bold">{sessionDetails?.pointsRequired} pts</span></p>
          <p className="text-xs text-amber-600">Customer must tap card on the ESP32 reader to complete.</p>
          <button
            onClick={() => { setSessionActive(false); setFiatAmount(''); setSelectedUserId(''); }}
            className="mt-2 px-3 py-1.5 bg-amber-200 hover:bg-amber-300 text-amber-900 rounded-lg text-xs font-semibold transition"
          >
            Cancel Session
          </button>
        </div>
      )}
    </div>
  );
}
